custom_css:
/* Neon Aurora Theme - 霓虹舒适版 */

/* 背景透明 */
body {
    background: transparent !important;
}

#chat {
    background: transparent !important;
}

/* 霓虹效果消息气泡 */
.mes {
    background: rgba(20, 25, 40, 0.55) !important;
    border-radius: 18px !important;
    backdrop-filter: blur(10px) !important;
    margin: 12px 0 !important;
    border: 2px solid;
    border-image: linear-gradient(135deg, rgba(100, 200, 255, 0.3), rgba(180, 100, 255, 0.3), rgba(255, 100, 200, 0.3)) 1 !important;
    box-shadow: 0 0 30px rgba(100, 200, 255, 0.1), inset 0 0 30px rgba(100, 200, 255, 0.03) !important;
    position: relative;
    overflow: hidden;
}

/* 气泡内部流光效果 */
.mes::before {
    content: '';
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(45deg, transparent, rgba(100, 200, 255, 0.1), transparent);
    z-index: -1;
    border-radius: 18px;
    animation: shimmer 8s ease-in-out infinite;
}

@keyframes shimmer {
    0%, 100% { opacity: 0.3; }
    50% { opacity: 0.8; }
}

/* 用户消息 - 蓝色霓虹 */
.mes.user {
    background: rgba(25, 40, 70, 0.6) !important;
    border-image: linear-gradient(135deg, rgba(80, 150, 255, 0.5), rgba(150, 100, 255, 0.5)) 1 !important;
    box-shadow: 0 0 40px rgba(80, 150, 255, 0.2), inset 0 0 40px rgba(80, 150, 255, 0.05) !important;
}

/* AI消息 - 紫色霓虹 */
.mes[isbot="true"] {
    background: rgba(40, 25, 60, 0.55) !important;
    border-image: linear-gradient(135deg, rgba(180, 100, 255, 0.5), rgba(255, 80, 180, 0.5)) 1 !important;
    box-shadow: 0 0 40px rgba(180, 100, 255, 0.2), inset 0 0 40px rgba(180, 100, 255, 0.05) !important;
}

/* 头像 - 霓虹光圈 */
.avatar {
    border-radius: 50% !important;
    border: 3px solid rgba(100, 200, 255, 0.5) !important;
    box-shadow: 0 0 20px rgba(100, 200, 255, 0.5), 0 0 40px rgba(180, 100, 255, 0.3), inset 0 0 20px rgba(100, 200, 255, 0.2) !important;
    transition: all 0.4s ease !important;
    animation: neonPulse 4s ease-in-out infinite;
}

@keyframes neonPulse {
    0%, 100% {
        box-shadow: 0 0 20px rgba(100, 200, 255, 0.5), 0 0 40px rgba(180, 100, 255, 0.3);
    }
    50% {
        box-shadow: 0 0 30px rgba(100, 200, 255, 0.8), 0 0 60px rgba(180, 100, 255, 0.5);
    }
}

.avatar:hover {
    border-color: rgba(150, 220, 255, 0.8) !important;
    box-shadow: 0 0 40px rgba(100, 200, 255, 0.9), 0 0 80px rgba(180, 100, 255, 0.6) !important;
    transform: scale(1.1) !important;
}

/* 头像图片 */
.avatar-img {
    width: 90px !important;
    height: 90px !important;
    object-fit: cover !important;
    border-radius: 50%;
}

/* 对话中的头像 */
.mes .avatar {
    width: 65px !important;
    height: 65px !important;
}

.mes .avatar-img {
    width: 100% !important;
    height: 100% !important;
}

/* 文字效果 */
.mes_text {
    text-shadow: 0 0 10px rgba(100, 200, 255, 0.3), 0 2px 4px rgba(0, 0, 0, 0.8) !important;
}

/* 代码块霓虹效果 */
pre {
    background: rgba(10, 15, 30, 0.8) !important;
    border: 1px solid rgba(100, 200, 255, 0.3) !important;
    border-radius: 10px !important;
    box-shadow: inset 0 0 30px rgba(100, 200, 255, 0.1) !important;
}

/* 滚动条 - 霓虹风格 */
::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-track {
    background: rgba(10, 15, 25, 0.5) !important;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(180deg, rgba(100, 200, 255, 0.6), rgba(180, 100, 255, 0.6)) !important;
    border-radius: 5px;
    box-shadow: 0 0 10px rgba(100, 200, 255, 0.5);
}

::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, rgba(120, 220, 255, 0.9), rgba(200, 120, 255, 0.9)) !important;
    box-shadow: 0 0 20px rgba(100, 200, 255, 0.8);
}

/* 输入框 - 霓虹边框 */
#form_prompt {
    background: rgba(15, 20, 35, 0.7) !important;
    border: 2px solid rgba(100, 200, 255, 0.3) !important;
    border-radius: 16px !important;
    backdrop-filter: blur(15px) !important;
    box-shadow: 0 0 30px rgba(100, 200, 255, 0.15), inset 0 0 30px rgba(100, 200, 255, 0.05) !important;
}

#form_prompt:focus {
    border-color: rgba(100, 200, 255, 0.6) !important;
    box-shadow: 0 0 40px rgba(100, 200, 255, 0.3), inset 0 0 40px rgba(100, 200, 255, 0.1) !important;
}

/* 发送按钮 - 渐变霓虹 */
#dialogue_send {
    background: linear-gradient(135deg, rgba(80, 180, 255, 0.7), rgba(180, 100, 255, 0.7)) !important;
    border: none !important;
    border-radius: 14px !important;
    box-shadow: 0 0 25px rgba(100, 200, 255, 0.5) !important;
    transition: all 0.3s ease !important;
    position: relative;
    overflow: hidden;
}

#dialogue_send::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: linear-gradient(45deg, transparent, rgba(255, 255, 255, 0.3), transparent);
    transform: rotate(45deg);
    animation: buttonShine 3s ease-in-out infinite;
}

@keyframes buttonShine {
    0% { transform: translateX(-100%) rotate(45deg); }
    100% { transform: translateX(100%) rotate(45deg); }
}

#dialogue_send:hover {
    background: linear-gradient(135deg, rgba(100, 200, 255, 0.9), rgba(200, 120, 255, 0.9)) !important;
    transform: translateY(-3px);
    box-shadow: 0 0 40px rgba(100, 200, 255, 0.8) !important;
}

/* 侧边栏 */
#right-nav-panel,
#left-nav-panel {
    background: rgba(12, 18, 30, 0.8) !important;
    backdrop-filter: blur(20px) !important;
    border: 1px solid rgba(100, 200, 255, 0.15);
    box-shadow: 0 0 40px rgba(100, 200, 255, 0.1) !important;
}

/* 顶部栏 */
#top-bar-holder {
    background: rgba(12, 18, 30, 0.9) !important;
    backdrop-filter: blur(20px) !important;
    border-bottom: 2px solid rgba(100, 200, 255, 0.2);
    box-shadow: 0 5px 30px rgba(100, 200, 255, 0.15) !important;
}
